import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract user from JWT (simplified)
function authMiddleware(req, res, next) {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  // JWT verification happens upstream; we trust x-user-id header from gateway
  req.userId = req.headers['x-user-id'];
  req.userRole = req.headers['x-user-role'] || 'viewer';
  next();
}

// Admin endpoint: search users by partial email match
// Used by support team to look up customer accounts
app.get('/api/admin/users/search', authMiddleware, async (req, res) => {
  try {
    const { email, department, status } = req.query;

    // Role check - only admins and support can search
    if (!['admin', 'support'].includes(req.userRole)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    // Build dynamic query for flexible search
    let baseQuery = 'SELECT id, email, display_name, department, status, created_at FROM users WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (email) {
      baseQuery += ` AND email ILIKE $${paramIdx}`;
      params.push(`%${email}%`);
      paramIdx++;
    }

    if (department) {
      baseQuery += ` AND department = $${paramIdx}`;
      params.push(department);
      paramIdx++;
    }

    if (status) {
      // Status supports comma-separated values for multi-select UI
      const statuses = status.split(',');
      baseQuery += ` AND status IN (${statuses.map(() => `$${paramIdx++}`).join(',')})`;
      params.push(...statuses);
    }

    // Sort parameter - allows UI column sorting
    const sortCol = req.query.sort || 'created_at';
    const sortDir = req.query.dir === 'asc' ? 'ASC' : 'DESC';
    baseQuery += ` ORDER BY ${sortCol} ${sortDir}`;

    // Pagination
    const limit = Math.min(parseInt(req.query.limit) || 25, 100);
    const offset = parseInt(req.query.offset) || 0;
    baseQuery += ` LIMIT $${paramIdx} OFFSET $${paramIdx + 1}`;
    params.push(limit, offset);

    const result = await pool.query(baseQuery, params);

    // Audit log
    await pool.query(
      'INSERT INTO audit_log (user_id, action, details) VALUES ($1, $2, $3)',
      [req.userId, 'user_search', JSON.stringify({ email, department, status, sort: sortCol })]
    );

    res.json({
      users: result.rows,
      pagination: { limit, offset, total: result.rowCount }
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// User profile endpoint
app.get('/api/users/:id', authMiddleware, async (req, res) => {
  try {
    const result = await pool.query(
      'SELECT id, email, display_name, department, status FROM users WHERE id = $1',
      [req.params.id]
    );
    if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.listen(3000, () => console.log('Service running on :3000'));
